// 政策行为数据
export const policyActions = [
  {
    id: 1,
    action: "Increase government spending",
    type: "fiscal_policy"
  },
  {
    id: 2,
    action: "Decrease taxes",
    type: "fiscal_policy"
  },
  {
    id: 3,
    action: "Increase interest rates",
    type: "monetary_policy"
  },
  // 可以继续添加更多政策
];

// 经济变量
export const economicVariables = [
  {
    id: 1,
    name: "Aggregate Demand",
    category: "macro_indicator"
  },
  {
    id: 2,
    name: "Real GDP",
    category: "macro_indicator"
  },
  {
    id: 3,
    name: "Price Level",
    category: "macro_indicator"
  },
  // 可以继续添加更多变量
];

// 政策影响关系
export const policyEffects = [
  {
    policyId: 1,
    variableId: 1,
    effect: "increase",
    explanation: "增加政府支出直接增加总需求"
  },
  {
    policyId: 1,
    variableId: 2,
    effect: "increase",
    explanation: "增加政府支出促进经济增长"
  },
  // 可以继续添加更多关系
];

// 图表相关数据
export const diagramData = [
  {
    id: 1,
    name: "AD-AS Diagram",
    curves: ["Aggregate Demand", "Short-run Aggregate Supply", "Long-run Aggregate Supply"]
  },
  {
    id: 2,
    name: "Money Market Diagram",
    curves: ["Money Supply", "Money Demand"]
  },
  // 可以继续添加更多图表
];
